def x_run_custom_trainer__mutmut_4(model, tokenizer, train_ds, val_ds, cfg: TrainCfg) -> dict[str, Any]:
    """Train ``model`` on ``train_ds`` using a minimal deterministic loop."""
    device = torch.device(cfg.device or ("XXcudaXX" if torch.cuda.is_available() else "cpu"))
