    metrics_stem = "metrics"
    if cfg.mlflow_enable:
        artifact_root = Path(cfg.checkpoint_dir or ".codex") / "mlflow"
        artifact_root.mkdir(parents=True, exist_ok=True)
        metrics_root = artifact_root
