                    params = {
                        "training.lr": cfg.lr,
                        "training.batch_size": cfg.batch_size,
                        "training.epochs": cfg.epochs,
                        "training.grad_accum": cfg.grad_accum,
                        "training.dtype": cfg.dtype,
                        "training.max_grad_norm": cfg.max_grad_norm,
                        "training.use_lora": cfg.use_lora,
                    }
