                        patience_ctr = 0
                        ckpt = Path(cfg.checkpoint_dir) / "best.ptz"
                        save_checkpoint(
                            ckpt,
                            model,
                            optimizer,
                            scheduler,
                            epoch + 1,
                            {
                                "global_step": global_step,
                                "best_val": best_val,
                                "step_in_epoch": 0,
                                "rng_state": dump_rng_state(),
                            },
                        )
