                if history:
                    final_payload["final/last_loss"] = float(history[-1])
                mlf.log_metrics(final_payload, step=global_step)
                for key, value in final_payload.items():
                    _append_metric(
                        {
                            "phase": "final",
                            "metric": key,
                            "value": float(value),
                            "step": global_step,
                        }
                    )
