                        if cfg.mlflow_enable:
                            try:
                                mlf.log_metrics(
                                    {f"eval/{k}": float(v) for k, v in numeric_metrics.items()},
                                    step=global_step,
                                )
                            except Exception as e:
                                logger.debug(f"Exception: {e}")
