            def __init__(self, target: Path) -> None:
                self._target = target

            def log(self, row: Mapping[str, object]) -> None:
                with self._target.open("a", encoding="utf-8") as handle:
                    handle.write(json.dumps(dict(row), ensure_ascii=False) + "\n")

