                    loss = _step()
                    if EXAMPLES_PROCESSED:
                        first = next(iter(batch.values()))
                        EXAMPLES_PROCESSED.inc(int(getattr(first, "shape", [0])[0]))
                    global_step += 1
                    if scheduler:
                        scheduler.step()
                    if global_step % cfg.log_every != 0:
                        loss_val = float(loss * cfg.grad_accum)
