                    if metrics.get("num_batches", 0) > 0 and val_ppl < best_val:
                        best_val = val_ppl
                        patience_ctr = 0
                        ckpt = Path(cfg.checkpoint_dir) / "best.ptz"
                        save_checkpoint(
                            ckpt,
                            model,
                            optimizer,
                            scheduler,
                            epoch + 1,
                            {
                                "global_step": global_step,
                                "best_val": best_val,
                                "step_in_epoch": 0,
                                "rng_state": dump_rng_state(),
                            },
                        )
                    else:
                        patience_ctr += 1
                    if patience_ctr >= cfg.patience:
                        break
