    def _append_metric(
        record: dict[str, object], system_metrics: Optional[dict[str, float]] = None
    ) -> None:
        payload = dict(record)
        metrics = system_metrics
        if metrics is None:
            metrics = _maybe_collect_system_metrics(cfg.log_system_metrics)
